def fill_enclosed(grid, color):
    """Every background cell not reachable from the grid border becomes `color`."""
    from collections import deque
    h, w = len(grid), len(grid[0])
    outside = [[False]*w for _ in range(h)]
    q = deque()
    for i in range(h):
        for j in (0, w-1):
            if grid[i][j] == 0 and not outside[i][j]:
                outside[i][j] = True; q.append((i, j))
    for j in range(w):
        for i in (0, h-1):
            if grid[i][j] == 0 and not outside[i][j]:
                outside[i][j] = True; q.append((i, j))
    while q:
        i, j = q.popleft()
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni, nj = i+di, j+dj
            if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == 0 and not outside[ni][nj]:
                outside[ni][nj] = True; q.append((ni, nj))
    return [[color if v == 0 and not outside[i][j] else v for j, v in enumerate(row)] for i, row in enumerate(grid)]
''')
